using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MarketSphere.Domain.Entities.Infrastructure;
namespace MarketSphere.Infrastructure.Persistence.Configurations.Infrastructure;
public sealed class OfflineSyncRecordConfiguration : IEntityTypeConfiguration<OfflineSyncRecord> { public void Configure(EntityTypeBuilder<OfflineSyncRecord> builder) { builder.ToTable("OfflineSyncRecords", t => t.HasCheckConstraint("CK_OfflineSyncRecords_RetryCount", "[RetryCount] >= 0")); builder.HasKey(x => x.OfflineSyncRecordID); builder.Property(x => x.LocalRecordKey).HasMaxLength(200).IsRequired(); builder.Property(x => x.EntityType).HasMaxLength(100).IsRequired(); builder.Property(x => x.OperationType).HasConversion<int>(); builder.Property(x => x.PayloadJson).HasColumnType("nvarchar(max)").IsRequired(); builder.Property(x => x.SyncStatus).HasConversion<int>(); builder.Property(x => x.LastError).HasMaxLength(2000); builder.HasIndex(x => new { x.UserSessionID, x.LocalRecordKey }).IsUnique(); builder.HasIndex(x => new { x.SyncStatus, x.RetryCount }); builder.HasOne(x => x.UserSession).WithMany().HasForeignKey(x => x.UserSessionID).OnDelete(DeleteBehavior.Restrict); } }
